`,n.jsx(t.p,{children:n.jsx(t.strong,{children:"Stacking (TearsheetPresence → StackProvider)"})}),`
`,n.jsx(t.pre,{children:n.jsx(t.code,{className:"language-jsx",children:`// Before
import { TearsheetPresence } from '@carbon/ibm-products';
<TearsheetPresence open={open1 || open2}>
  <Tearsheet open={open1} onClose={() => setOpen1(false)}>
    ...
  </Tearsheet>
  <Tearsheet open={open2} onClose={() => setOpen2(false)}>
    ...
  </Tearsheet>
</TearsheetPresence>;

// After
import {
  StackProvider,
  preview__Tearsheet as Tearsheet,
} from '@carbon/ibm-products';
<StackProvider stackStepSize="lg">
  <Tearsheet open={open1} onClose={() => setOpen1(false)}>
    ...
  </Tearsheet>
  <Tearsheet open={open2} onClose={() => setOpen2(false)}>
    ...
  </Tearsheet>
</StackProvider>;
`})}),`
